import{_ as i,l as r,o as e,c as s,v as l,p as n,x as o,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"寄存器分配着色","description":"","frontmatter":{"title":"寄存器分配着色","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/regalloc-color.md","filePath":"cs/regalloc-color.md","lastUpdated":1789023840000}'),p={name:"cs/regalloc-color.md"};function _(E,a,A,m,f,u){const t=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="寄存器分配着色" tabindex="-1">寄存器分配着色 <a class="header-anchor" href="#寄存器分配着色" aria-label="Permalink to &quot;寄存器分配着色&quot;">​</a></h1><div class="epigraph"><p>同时活跃的虚拟寄存器连边；物理寄存器是颜色。颜色不够就溢出到栈槽。</p><footer>—— 据 Chaitin et al., Register Allocation via Coloring, 1981；Chaitin, Register Allocation and Spilling, 1982 整理</footer></div><p>上一课<a href="/cs/instruction-sched">指令调度</a>留下带虚拟寄存器的机器指令。<a href="/cs/dataflow-liveness">活跃变量</a>给出同时存活。本课不重选 opcode。缺口是：把无限虚拟名映到有限物理寄存器，或插入 spill。图着色是经典方法；一般图着色 <a href="/cs/npc-canonical">NPC</a>，编译器用启发式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>冲突图：节点为虚拟寄存器（或 SSA 名），边表示不能同寄存器。\\(K\\) 个物理寄存器则求 \\(K\\)-着色。 Briggs 等：简化低度数节点、压栈、再着色，失败则选溢出候选、重写再来。缺口是这张图与溢出循环，不是再跑一遍活跃分析的方程。</p><p><a href="/cs/calling-convention-stack">调用约定与栈</a>已说明调用者/被调用者保存；本课着色必须尊重：跨调用活跃的名字不能占用 caller-save 而不保存。具体哪几个号留给 ABI 课钉死，本课只承认类别（整数/浮点分图）。</p><h3 id="启发式不是多项式最优" tabindex="-1">启发式不是多项式最优 <a class="header-anchor" href="#启发式不是多项式最优" aria-label="Permalink to &quot;启发式不是多项式最优&quot;">​</a></h3><p>Chaitin 把分配写成着色。NPC 课已警告：不要声称最优多项式。启发式在实际 CFG 上够用。线性扫描是另一派，本课点名对照，不写完。</p><p><span class="marginnote">Chaitin 1981/82（PLDI）。Briggs 的乐观着色减少不必要溢出。SSA 上着色有和弦图特例可多项式，离开 SSA 后一般仍难。本课启发式为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建冲突图。合并拷贝（不增加冲突时收缩边）以消 <code>move</code>。简化：\\(deg\\lt K\\) 的点压栈；否则挑溢出代价低的。弹出着色；失败插入 <code>store/load</code> 到栈槽，更新 IR，可能再选指令。</p>',11)),(e(),n(h,null,{default:o(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIVE%5B%22%E6%B4%BB%E8%B7%83%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20IG%5B%22%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A%20%20IG%20--%3E%20COL%5B%22K-%E7%9D%80%E8%89%B2%E5%90%AF%E5%8F%91%E5%BC%8F%22%5D%0A%20%20COL%20--%3E%20OK%5B%22%E7%89%A9%E7%90%86%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20COL%20--%3E%20SP%5B%22%E6%BA%A2%E5%87%BA%E5%86%8D%E5%86%99%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>栈槽寻址用帧指针，组成课的栈已有；偏移在 ABI 帧布局里统一。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>溢出增加访存，改变活跃，故可能迭代。φ 在着色前应已拆或与并行拷贝一起处理。不要在本课生成完整 System V 序言。</p><p>与 Cache 课：溢出落入栈，局部性变差，不在分配器里模拟 Cache。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写窥孔、不输出目标文件格式。不把图着色当通用 NPC 求解作业。后课默认：函数体已是物理寄存器指令加 spill。窥孔在短窗口上再改写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冲突图 + \\(K\\)-着色；不够则溢出。</li><li>一般着色 NPC，编译器用简化启发式。</li><li>调用保存类别约束调色板。</li><li>出处：Chaitin et al., 1981, 1982；龙书第 8 章。</li></ul>',8))])}const g=i(p,[["render",_]]);export{C as __pageData,g as default};
